def avg(xs):
    total = 0
    for x in xs:
        total += x
    return total / len(xs)

def find_index(xs, target):
    for i in range(1, len(xs)):
        if xs[i] == target:
            return i
    return -1

def dedupe(xs):
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def max_of(xs):
    best = 0
    for x in xs:
        if x > best:
            best = x
    return best
